import pyomo.environ as pyo

DATA = {
    "projects": ["X", "Y"],
    "cost": {"X": 5, "Y": 8},
    "effectiveness_coef": {"X": 2, "Y": 1},
    "max_total_allocation": 100,
    "min_effectiveness": 50,
    "max_balance_diff": 30,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PROJECTS = pyo.Set(initialize=d["projects"])

    model.alloc = pyo.Var(
        model.PROJECTS,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost"][p] * m.alloc[p] for p in m.PROJECTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_allocation_rule(m):
        return sum(m.alloc[p] for p in m.PROJECTS) <= d["max_total_allocation"]

    model.total_allocation = pyo.Constraint(rule=total_allocation_rule)

    def effectiveness_rule(m):
        return sum(
            d["effectiveness_coef"][p] * m.alloc[p] for p in m.PROJECTS
        ) >= d["min_effectiveness"]

    model.effectiveness = pyo.Constraint(rule=effectiveness_rule)

    def balance_xy_rule(m):
        return m.alloc["X"] - m.alloc["Y"] <= d["max_balance_diff"]

    model.balance_xy = pyo.Constraint(rule=balance_xy_rule)

    def balance_yx_rule(m):
        return m.alloc["Y"] - m.alloc["X"] <= d["max_balance_diff"]

    model.balance_yx = pyo.Constraint(rule=balance_yx_rule)

    return model
